import { describe, it, expect } from "vitest";
import { createQuestionForms } from "../src/chat/question-form-drafts.js";

/**
 * Regression tests for the question-form drafts webview controller.
 *
 * Requirement 1 ("late recovery doesn't overwrite edits"): a delayed
 * questionDraftSnapshot must only restore fields when the form has no new
 * user input (f.dirty === false). Once the user types, later snapshots must
 * be ignored so their new input is preserved.
 *
 * Requirement 2 ("select/checkbox declaration order preserved"): both
 * restore() and capture() map controls to draftFields by declaration index,
 * so values land on the control declared for their key regardless of the
 * order in which a snapshot's fields array is presented, and capture emits
 * fields in the same order the fields were declared.
 */

/** Minimal control node used by the webview controller. */
class Node {
  constructor(tagName) {
    this.tagName = tagName;
    this._value = "";
    this._checked = false;
    this.disabled = false;
    this.className = "approval";
    this.textContent = "";
    this.isConnected = true;
    this._children = [];
    this._listeners = {};
  }
  get value() {
    return this._value;
  }
  set value(v) {
    this._value = String(v);
  }
  get checked() {
    return this._checked;
  }
  set checked(c) {
    this._checked = Boolean(c);
  }
  appendChild(node) {
    this._children.push(node);
    return node;
  }
  setAttribute(name, value) {
    this[`attr:${name}`] = value;
  }
  addEventListener(type, fn) {
    (this._listeners[type] = this._listeners[type] || []).push(fn);
  }
  dispatchEvent(type) {
    for (const fn of this._listeners[type] || []) fn();
  }
  querySelectorAll(selector) {
    const tags = selector.split(",").map((t) => t.trim());
    const found = [];
    const walk = (node) => {
      if (node.tagName && tags.includes(node.tagName)) found.push(node);
      for (const child of node._children || []) walk(child);
    };
    walk(this);
    return found;
  }
}

const document = { createElement: (tag) => new Node(tag) };

function makeMessage(overrides = {}) {
  return {
    id: "req-1",
    convId: "conv-1",
    draftKey: "dk-1",
    questionInstance: "inst-1",
    questionKey: "qk-1",
    questionState: "draft",
    draftStorage: true,
    draftFields: [
      { key: "agree", kind: "checkbox", label: "Agree" },
      { key: "tier", kind: "select", label: "Tier" },
      { key: "comment", kind: "text", label: "Comment" },
    ],
    ...overrides,
  };
}

function makeCard() {
  const card = new Node("div");
  const agree = new Node("input");
  const tier = new Node("select");
  const comment = new Node("textarea");
  card.appendChild(agree);
  card.appendChild(tier);
  card.appendChild(comment);
  return { card, agree, tier, comment };
}

function snapshot(m, fields, state = "draft") {
  return {
    kind: "questionDraftSnapshot",
    questionInstance: m.questionInstance,
    questionKey: m.questionKey,
    draftKey: m.draftKey,
    convId: m.convId,
    state,
    fields,
  };
}

describe("question-form-drafts late recovery", () => {
  it("applies a snapshot when the form is clean (not dirty)", () => {
    const forms = createQuestionForms({ document, vscode: { postMessage: () => {} } });
    const m = makeMessage();
    const { card, agree, tier, comment } = makeCard();
    forms.attach(card, m);

    forms.receive(
      snapshot(m, [
        { key: "agree", value: true },
        { key: "tier", value: "premium" },
        { key: "comment", value: "hello" },
      ]),
    );

    expect(agree.checked).toBe(true);
    expect(tier.value).toBe("premium");
    expect(comment.value).toBe("hello");
  });

  it("does not overwrite user input with a late snapshot once the form is dirty", () => {
    const forms = createQuestionForms({ document, vscode: { postMessage: () => {} } });
    const m = makeMessage();
    const { card, comment } = makeCard();
    forms.attach(card, m);

    // User edits the comment field (marks the form dirty).
    comment.value = "user edit";
    comment.dispatchEvent("input");

    // A delayed snapshot arrives with a different value for the same field.
    forms.receive(
      snapshot(m, [
        { key: "agree", value: true },
        { key: "tier", value: "premium" },
        { key: "comment", value: "server overwrite" },
      ]),
    );

    expect(comment.value).toBe("user edit");
  });

  it("restores values onto the control declared for each key, in declaration order", () => {
    const forms = createQuestionForms({ document, vscode: { postMessage: () => {} } });
    const m = makeMessage(); // draftFields: agree(checkbox), tier(select), comment(text)
    const { card, agree, tier, comment } = makeCard();
    forms.attach(card, m);

    // The snapshot presents the fields in a different order than declared.
    forms.receive(
      snapshot(m, [
        { key: "comment", value: "note" },
        { key: "agree", value: true },
        { key: "tier", value: "premium" },
      ]),
    );

    expect(agree.checked).toBe(true);
    expect(tier.value).toBe("premium");
    expect(comment.value).toBe("note");
  });

  it("leaves a control untouched when its key is missing from the snapshot", () => {
    const forms = createQuestionForms({ document, vscode: { postMessage: () => {} } });
    const m = makeMessage();
    const { card, agree, tier, comment } = makeCard();
    forms.attach(card, m);

    // Pre-set values directly (no events dispatched, so the form stays clean).
    agree.checked = true;
    comment.value = "kept";

    forms.receive(snapshot(m, [{ key: "tier", value: "premium" }]));

    expect(tier.value).toBe("premium");
    expect(agree.checked).toBe(true);
    expect(comment.value).toBe("kept");
  });

  it("captures fields in the same order the fields were declared", () => {
    const posted = [];
    const forms = createQuestionForms({
      document,
      vscode: { postMessage: (msg) => posted.push(msg) },
    });
    const m = makeMessage(); // draftFields: agree(checkbox), tier(select), comment(text)
    const { card, comment } = makeCard();
    forms.attach(card, m);

    comment.value = "note";
    comment.dispatchEvent("input");

    const update = posted.find((p) => p.type === "questionDraftUpdate");
    expect(update).toBeDefined();
    expect(update.fields.map((f) => f.key)).toEqual(["agree", "tier", "comment"]);
    expect(update.fields.map((f) => f.value)).toEqual(["", "", "note"]);
  });
});

import { describe, expect, it } from "vitest";
import { Window } from "happy-dom";
import { createQuestionForms } from "../src/chat/question-form-drafts.js";

// Independent regression coverage for "late load does not overwrite edits".
// Production path exercised: createQuestionForms().attach / .receive against a
// happy-dom document and a VS Code api stub (getState/setState/postMessage).

function module(m, html, draftFields, { backup = {} } = {}) {
  const window = new Window({
    settings: {
      enableJavaScriptEvaluation: true,
      disableCSSFileLoading: true,
      disableJavaScriptFileLoading: true,
    },
  });
  const sent = [];
  let state = backup;
  const vscode = {
    getState: () => state,
    setState: (v) => {
      state = v;
    },
    postMessage: (m) => sent.push(m),
  };
  const card = window.document.createElement("div");
  card.innerHTML = html;
  const forms = createQuestionForms({
    document: window.document,
    vscode,
  });
  forms.attach(card, { ...m, draftFields });
  return { window, card, sent, forms };
}

const textMeta = {
  questionInstance: "q1",
  questionKey: "k1",
  draftKey: "d1",
  convId: "c1",
  questionState: "draft",
  draftStorage: true,
  draftFields: [{ key: "answer", kind: "text" }],
};

const mixedMeta = {
  questionInstance: "q2",
  questionKey: "k2",
  draftKey: "d2",
  convId: "c2",
  questionState: "draft",
  draftStorage: true,
  draftFields: [
    { key: "color", kind: "select" },
    { key: "consent", kind: "checkbox" },
  ],
};

describe("late draft load does not overwrite edits", () => {
  it("keeps a user edit when a late snapshot returns after the edit", () => {
    const h = module(textMeta, "<input/>", textMeta.draftFields);
    const input = h.card.querySelector("input");
    input.value = "typed after load started";
    input.dispatchEvent(new h.window.Event("input"));
    expect(h.sent.at(-1)).toMatchObject({ type: "questionDraftUpdate" });
    // Late recovery resolves; the draft fields it carries are stale.
    h.forms.receive({
      ...textMeta,
      kind: "questionDraftSnapshot",
      state: "draft",
      fields: [{ key: "answer", value: "stale host copy" }],
    });
    expect(input.value).toBe("typed after load started");
  });

  it("applies the host snapshot when no newer edit exists", () => {
    const h = module(textMeta, "<input/>", textMeta.draftFields);
    h.forms.receive({
      ...textMeta,
      kind: "questionDraftSnapshot",
      state: "draft",
      fields: [{ key: "answer", value: "stale host copy" }],
    });
    expect(h.card.querySelector("input").value).toBe("stale host copy");
  });
});

describe("select/checkbox declaration order preserved on restore", () => {
  const html =
    '<select><option value="red">Red</option><option value="blue">Blue</option>' +
    "</select><input type=\"checkbox\"/>";

  it("assigns checkbox and select by declared role regardless of field order", () => {
    const h = module(mixedMeta, html, mixedMeta.draftFields);
    h.forms.receive({
      ...mixedMeta,
      kind: "questionDraftSnapshot",
      state: "draft",
      // Fields arrive in reverse declaration order on purpose.
      fields: [
        { key: "consent", value: true },
        { key: "color", value: "blue" },
      ],
    });
    const [select, checkbox] = h.card.querySelectorAll(
      "select,input[type=checkbox]",
    );
    expect(select.value).toBe("blue");
    expect(checkbox.checked).toBe(true);
  });

  it("does not mark a checkbox checked from a non-boolean value, yet restores the select", () => {
    const h = module(mixedMeta, html, mixedMeta.draftFields);
    h.forms.receive({
      ...mixedMeta,
      kind: "questionDraftSnapshot",
      state: "draft",
      fields: [
        { key: "color", value: "blue" },
        { key: "consent", value: "true" },
      ],
    });
    const [select, checkbox] = h.card.querySelectorAll(
      "select,input[type=checkbox]",
    );
    expect(select.value).toBe("blue");
    expect(checkbox.checked).toBe(false);
  });
});

