/** Embedded verbatim in the Webview; no Node or VS Code host dependencies. */
function createQuestionForms({ document, vscode }) {
  const forms = new Map();
  const backup = vscode.getState?.()?.questionDrafts || [];

  function identity(m) {
    return {
      convId: m.convId,
      draftKey: m.draftKey,
      id: m.id,
      questionInstance: m.questionInstance,
      questionKey: m.questionKey,
    };
  }
  function remember() {
    const saved = [...forms.values()]
      .filter((f) => f.dirty && f.m.draftStorage)
      .slice(-16)
      .map((f) => ({ ...identity(f.m), fields: f.fields }));
    while (JSON.stringify(saved).length > 65536) saved.shift();
    vscode.setState?.({ ...vscode.getState?.(), questionDrafts: saved });
  }
  function state(f, value, text) {
    f.state = value;
    for (const control of f.card.querySelectorAll(
      "input,select,textarea,button",
    ))
      control.disabled = value !== "draft";
    f.card.className = value === "archived" ? "approval done" : "approval";
    f.note.textContent =
      text ||
      {
        draft: "",
        saving: "Saving answer…",
        pending: "Submitted; waiting for agent confirmation",
        unknown: "Delivery is unknown; no automatic retry.",
        archived: "Question closed; saved text remains editable",
      }[value] ||
      "";
  }
  function restore(f, fields) {
    const values = new Map(fields.map((v) => [v.key, v.value]));
    f.controls.forEach((control, index) => {
      const d = f.m.draftFields?.[index];
      if (!d || d.kind === "password" || !values.has(d.key)) return;
      const value = values.get(d.key);
      if (d.kind === "checkbox" && typeof value === "boolean")
        control.checked = value;
      else if (typeof value === "string") control.value = value;
    });
  }
  function capture(f) {
    return f.controls.flatMap((control, index) => {
      const d = f.m.draftFields?.[index];
      return !d || d.kind === "password"
        ? []
        : [
            {
              key: d.key,
              value: d.kind === "checkbox" ? control.checked : control.value,
            },
          ];
    });
  }
  function update(f) {
    f.fields = capture(f);
    f.revision++;
    f.dirty = true;
    remember();
    if (f.m.draftStorage)
      vscode.postMessage({
        type: "questionDraftUpdate",
        ...identity(f.m),
        fields: f.fields,
        revision: f.revision,
      });
  }
  function attach(card, m) {
    const prior = forms.get(m.questionInstance);
    const f = {
      m,
      card,
      controls: [...card.querySelectorAll("input,select,textarea")],
      fields: [],
      revision: 0,
      dirty: false,
    };
    f.note = document.createElement("div");
    f.note.className = "info";
    f.note.setAttribute("aria-live", "polite");
    card.appendChild(f.note);
    forms.set(m.questionInstance, f);
    if (forms.size > 128) {
      for (const [key, form] of forms) {
        if (!form.card.isConnected && key !== m.questionInstance)
          forms.delete(key);
        if (forms.size <= 128) break;
      }
    }
    const local = prior?.dirty
      ? prior
      : backup.find(
          (b) =>
            b.questionInstance === m.questionInstance &&
            b.questionKey === m.questionKey &&
            b.draftKey === m.draftKey &&
            b.convId === m.convId,
        );
    if (local && m.questionState === "draft") {
      restore(f, local.fields);
      update(f);
    }
    state(
      f,
      m.questionState || "draft",
      m.recoveryError
        ? "Question draft recovery unavailable: " + m.recoveryError
        : "",
    );
    for (const control of f.controls) {
      control.addEventListener("input", () => {
        if (f.state === "draft") update(f);
      });
      control.addEventListener("change", () => {
        if (f.state === "draft") update(f);
      });
    }
    if (m.draftStorage)
      vscode.postMessage({ type: "questionDraftLoad", ...identity(m) });
    return f;
  }
  function submit(card, m, type, answer) {
    const f = forms.get(m.questionInstance);
    if (!f || f.card !== card || f.state !== "draft") return;
    const fields = capture(f);
    state(f, "saving");
    vscode.postMessage({
      type,
      ...identity(m),
      answer,
      fields,
      revision: ++f.revision,
    });
  }
  function receive(m) {
    if (
      ![
        "questionDraftSnapshot",
        "questionDraftError",
        "questionState",
      ].includes(m.kind)
    )
      return false;
    const f = forms.get(m.questionInstance);
    if (
      !f ||
      f.m.questionKey !== m.questionKey ||
      f.m.draftKey !== m.draftKey ||
      f.m.convId !== m.convId
    )
      return true;
    if (m.kind === "questionDraftSnapshot") {
      if (!f.dirty && f.state === "draft" && m.state === "draft")
        restore(f, m.fields || []);
      // A reload must preserve the host's pending/unknown response reservation.
      if (m.state !== "draft") state(f, m.state);
    } else if (m.kind === "questionState") state(f, m.state, m.text);
    else f.note.textContent = "Draft could not be saved: " + m.text;
    return true;
  }
  return { attach, submit, receive };
}
module.exports = { createQuestionForms };

import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs/promises";
import path from "node:path";
import { tmpdir } from "node:os";
import { randomUUID } from "node:crypto";
import { Window } from "happy-dom";
import { DraftStore } from "../../../vscode-extension/src/chat/draft-store.js";
import { QuestionDrafts } from "../../../vscode-extension/src/chat/question-drafts.js";
import {
  questionIdentity,
  questionFields,
  normalizeQuestionFields,
} from "../../../vscode-extension/src/chat/question-draft-contract.js";
import { ChatViewProvider } from "../../../vscode-extension/src/chat/chat-view.js";
import { buildChatHtml } from "../../../vscode-extension/src/chat/chat-html.js";

const cleanups = [];
afterEach(async () => {
  for (const fn of cleanups.splice(0).reverse()) await fn();
});
async function storage() {
  const root = await fs.mkdtemp(path.join(tmpdir(), "cc-question-"));
  cleanups.push(() => fs.rm(root, { recursive: true, force: true }));
  return root;
}
const binding = {
  backgroundAgentId: null,
  sessionId: "session-1",
  turnId: "turn-1",
  toolUseId: "tool-1",
  sequence: 1,
};
const request = {
  kind: "question",
  id: "q1",
  question: "Choose a target",
  binding,
};
const values = [{ key: "answer", value: "half entered 中文" }];
const payload = (q, extra = {}) => ({
  ...q,
  fields: values,
  revision: 1,
  ...extra,
});
function controller(store, overrides = {}) {
  cleanups.push(async () => {
    let queue;
    do {
      queue = store.queue;
      await queue;
    } while (queue !== store.queue);
  });
  const conv = {
    id: "a",
    sessionId: "session-1",
    draftKey: randomUUID(),
    _sessionToken: {},
    session: { running: true, sendEvent: vi.fn(() => true) },
    ...overrides,
  };
  const messages = [];
  const drafts = new QuestionDrafts({
    store,
    getConversation: (id) => (id === conv.id ? conv : null),
    post: (m) => messages.push(m),
    refresh: () => {},
  });
  return { drafts, conv, messages };
}
function ui(backup = {}) {
  const window = new Window({
    settings: {
      enableJavaScriptEvaluation: true,
      disableCSSFileLoading: true,
      disableJavaScriptFileLoading: true,
    },
  });
  cleanups.push(() => window.happyDOM.abort());
  const sent = [];
  let state = backup;
  window.acquireVsCodeApi = () => ({
    postMessage: (m) => sent.push(m),
    getState: () => state,
    setState: (v) => {
      state = v;
    },
  });
  window.document.write(
    buildChatHtml({ nonce: "n", cspSource: "vscode-resource:" }),
  );
  const emit = (data) =>
    window.dispatchEvent(new window.MessageEvent("message", { data }));
  const card = (q) => window.document.getElementById("q-" + q.questionInstance);
  return { window, sent, emit, card, state: () => state };
}

describe("question recovery authority and persistence", () => {
  it("recovers an unfinished bound question in a fresh host without sending an answer", async () => {
    const root = await storage();
    const first = controller(new DraftStore(root));
    const q = first.drafts.register(first.conv, request);
    await first.drafts.save(payload(q));
    const next = controller(new DraftStore(root), {
      draftKey: first.conv.draftKey,
    });
    const restored = next.drafts.register(next.conv, request);
    expect(restored.questionInstance).not.toBe(q.questionInstance);
    await next.drafts.restore(restored);
    expect(next.messages.at(-1)).toMatchObject({
      kind: "questionDraftSnapshot",
      fields: values,
      state: "draft",
    });
    expect(next.conv.session.sendEvent).not.toHaveBeenCalled();
    await next.drafts.save(
      payload(restored, { fields: [{ key: "answer", value: "finished" }] }),
    );
    expect(
      (await next.drafts.store.view(first.conv.draftKey)).questions,
    ).toHaveLength(1);
  });

  it("archives cancellations, schema changes and late edits without reviving the request", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    await h.drafts.save(payload(q));
    const changed = h.drafts.register(h.conv, {
      ...request,
      options: ["a", "b"],
    });
    await h.drafts.save(
      payload(q, { fields: [{ key: "answer", value: "late text" }] }),
    );
    await h.drafts.answer(payload(q, { answer: "stale" }));
    await h.drafts.restore(changed);
    expect(h.messages.at(-1).fields).toEqual([]);
    expect(h.conv.session.sendEvent).not.toHaveBeenCalled();
    expect(
      (await h.drafts.store.view(h.conv.draftKey)).questions[0],
    ).toMatchObject({ status: "archived", text: "Answer: late text" });
  });

  it("does not restore unbound or already submitted answers as a new live form", async () => {
    const root = await storage();
    for (const bound of [false, true]) {
      const h = controller(new DraftStore(root));
      const original = { ...request, binding: bound ? binding : undefined };
      const q = h.drafts.register(h.conv, original);
      await h.drafts.save(payload(q));
      if (bound) await h.drafts.answer(payload(q, { answer: "sent" }));
      const next = controller(new DraftStore(root), {
        draftKey: h.conv.draftKey,
      });
      const nextQ = next.drafts.register(next.conv, original);
      await next.drafts.restore(nextQ);
      expect(next.messages.at(-1).fields).toEqual([]);
      expect(
        (await next.drafts.store.view(h.conv.draftKey)).questions[0].text,
      ).toContain("half entered");
      expect(next.conv.session.sendEvent).not.toHaveBeenCalled();
    }
  });

  it("reserves one response, persists before writing, and leaves failed delivery unknown", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    h.conv.session.sendEvent.mockReturnValue(false);
    await Promise.all([
      h.drafts.answer(payload(q, { answer: "x" })),
      h.drafts.answer(payload(q, { answer: "x" })),
    ]);
    expect(h.conv.session.sendEvent).toHaveBeenCalledOnce();
    expect(h.messages.at(-1)).toMatchObject({ state: "unknown" });
    expect(
      (await h.drafts.store.view(h.conv.draftKey)).questions[0].status,
    ).toBe("archived");
    await h.drafts.answer(payload(q, { answer: "retry" }));
    expect(h.conv.session.sendEvent).toHaveBeenCalledOnce();
  });

  it("does not dispatch on storage failure or a reset during the save", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    await h.drafts.restore(q);
    const save = vi
      .spyOn(h.drafts.store, "saveQuestion")
      .mockRejectedValueOnce(new Error("disk full"));
    await h.drafts.answer(payload(q, { answer: "x" }));
    expect(h.messages.at(-1)).toMatchObject({
      state: "draft",
      text: "Answer was not sent: disk full",
    });
    save.mockRestore();
    let release;
    const original = h.drafts.store.saveQuestion.bind(h.drafts.store);
    vi.spyOn(h.drafts.store, "saveQuestion").mockImplementation(
      async (...args) => {
        await new Promise((resolve) => {
          release = resolve;
        });
        return original(...args);
      },
    );
    const sending = h.drafts.answer(payload(q, { answer: "x" }));
    await vi.waitFor(() => expect(release).toBeTypeOf("function"));
    h.conv._sessionToken = {};
    release();
    await sending;
    expect(h.conv.session.sendEvent).not.toHaveBeenCalled();
  });

  it("keeps deferred questions across turn end and bounds stored questions", async () => {
    const h = controller(new DraftStore(await storage()));
    const blocking = h.drafts.register(h.conv, request);
    const deferred = h.drafts.register(h.conv, {
      ...request,
      id: "later",
      blocking: false,
    });
    await h.drafts.save(payload(blocking));
    await h.drafts.save(payload(deferred));
    h.drafts.archiveConversation(h.conv, { blockingOnly: true });
    expect(h.drafts.match(deferred).state).toBe("draft");
    expect(h.drafts.match(blocking).state).toBe("archived");
    for (let i = 2; i < 16; i++)
      await h.drafts.save(
