import { describe, it, expect } from "vitest";
import { createQuestionForms } from "../src/chat/question-form-drafts.js";

/**
 * Regression tests for the question-form drafts webview controller.
 *
 * Requirement 1 ("late recovery doesn't overwrite edits"): a delayed
 * questionDraftSnapshot must only restore fields when the form has no new
 * user input (f.dirty === false). Once the user types, later snapshots must
 * be ignored so their new input is preserved.
 *
 * Requirement 2 ("select/checkbox declaration order preserved"): both
 * restore() and capture() map controls to draftFields by declaration index,
 * so values land on the control declared for their key regardless of the
 * order in which a snapshot's fields array is presented, and capture emits
 * fields in the same order the fields were declared.
 */

/** Minimal control node used by the webview controller. */
class Node {
  constructor(tagName) {
    this.tagName = tagName;
    this._value = "";
    this._checked = false;
    this.disabled = false;
    this.className = "approval";
    this.textContent = "";
    this.isConnected = true;
    this._children = [];
    this._listeners = {};
  }
  get value() {
    return this._value;
  }
  set value(v) {
    this._value = String(v);
  }
  get checked() {
    return this._checked;
  }
  set checked(c) {
